def solve(isConnected):
    n = len(isConnected)
    visited = [False] * n
    provinces = 0
    def dfs(i):
        for j in range(n):
            if isConnected[i][j] == 1 and not visited[j]:
                visited[j] = True
                dfs(j)
    for i in range(n):
        if not visited[i]:
            provinces += 1
            visited[i] = True
            dfs(i)
    return provinces

